#!/usr/bin/env python3
"""Generate our own branded Noorani Qaida PDF (A4). Every letter/haraka combination is generated by code (no typed drills).
Quranic text (Huroof Muqatta'at, Al-Fatiha) comes from the King Fahd Complex Uthmani text in data/quran-uthmani.json.
Usage: python3 scripts/build_qaida_pdf.py <fonts_dir>  (fontsource packages for amiri, manrope, fraunces)"""
import os, sys, json, subprocess, html as H

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
FONTS = sys.argv[1] if len(sys.argv) > 1 else "."
Q = json.load(open(os.path.join(ROOT, "data", "quran-uthmani.json")))
OUT_HTML = os.path.join(os.environ.get("TMPDIR", "/tmp"), "qaida.html")
OUT_PDF = os.path.join(ROOT, "downloads", "noorani-qaida-quran-online-tarteel.pdf")

F, K, D = "َ", "ِ", "ُ"          # fatha, kasra, damma
FT, KT, DT = "ً", "ٍ", "ٌ"       # tanween
SUK, SHAD, MADD = "ْ", "ّ", "ٓ"
KZ, KE, UP = "ٰ", "ٖ", "ٗ"       # khari zabar, khari zer, ulta pesh
ZWJ = "‍"

LETTERS = [("ا", "Alif"), ("ب", "Ba"), ("ت", "Ta"), ("ث", "Tha"), ("ج", "Jeem"), ("ح", "Ha"), ("خ", "Kha"), ("د", "Dal"), ("ذ", "Dhal"),
           ("ر", "Ra"), ("ز", "Zay"), ("س", "Seen"), ("ش", "Sheen"), ("ص", "Saad"), ("ض", "Daad"), ("ط", "Taa"), ("ظ", "Zaa"), ("ع", "Ain"),
           ("غ", "Ghain"), ("ف", "Fa"), ("ق", "Qaf"), ("ك", "Kaf"), ("ل", "Lam"), ("م", "Meem"), ("ن", "Noon"), ("و", "Waw"), ("ه", "Ha"),
           ("ء", "Hamza"), ("ي", "Ya")]
NONJOIN = set("اأإدذرزوء")
CONS = [l for l, _ in LETTERS if l not in ("ا",)]  # consonants for haraka drills (alif row uses hamza)


def first_word(s, a=1):
    return Q[s - 1]["verses"][a - 1]["text"].split(" ")[0].rstrip("ۚۖۗۛ")


def grid(cells, cols=6, cls=""):
    return f'<div class="grid c{cols} {cls}">' + "".join(
        f'<div class="cell"><span class="ar" lang="ar">{c[0]}</span>' + (f'<span class="nm">{H.escape(c[1])}</span>' if len(c) > 1 and c[1] else "") + "</div>"
        for c in cells) + "</div>"


def page(num, title, urdu, intro, body):
    return (f'<section class="pg"><header><span class="ln">Lesson {num}</span><h2>{title}</h2><span class="ur">{urdu}</span></header>'
            f'<p class="intro">{intro}</p>{body}<footer>quranonlinetarteel.net · Free for personal and family use · Learn with a female teacher: 2 free classes</footer></section>')


def with_h(l, h):
    return ("أ" if l == "ا" else ("إ" if (l == "ا" and h == K) else l)) + h


rows_h = []
for l in ["ا"] + CONS:
    base = l
    cells = []
    for h in (F, K, D):
        b = ("إ" if h == K else "أ") if l == "ا" else base
        cells.append((b + h, ""))
    rows_h.append(cells)

pages = []
# Lesson 1
pages.append(page(1, "Single Letters", "Huroof-e-Mufradaat",
                  "Learn the name and sound of each letter, reading from right to left. Point to each letter and say its name with your teacher.",
                  grid([(l, n) for l, n in LETTERS], 6, "big rtl")))
# Lesson 2 letter shapes
shape_cells = []
for l, n in LETTERS:
    if l in ("ء",):
        continue
    if l in NONJOIN:
        shape_cells.append((f"{l}&nbsp;&nbsp;{ZWJ}{l}", n))
    else:
        shape_cells.append((f"{l}&nbsp;&nbsp;{l}{ZWJ}&nbsp;&nbsp;{ZWJ}{l}{ZWJ}&nbsp;&nbsp;{ZWJ}{l}", n))
pages.append(page(2, "Joined Letters and Their Shapes", "Huroof-e-Murakkabaat",
                  "Letters change shape when they join. Each box shows the letter alone, then at the start, middle and end of a word. Six letters (ا د ذ ر ز و) never join to the letter after them.",
                  grid(shape_cells, 4, "shapes rtl")))
# Lesson 3 muqattaat
muq = [(2, 1), (7, 1), (10, 1), (13, 1), (19, 1), (20, 1), (26, 1), (27, 1), (36, 1), (38, 1), (40, 1), (42, 2), (50, 1), (68, 1)]
pages.append(page(3, "Disjoined Letters", "Huroof-e-Muqatta'at",
                  "Some surahs begin with letters that are read one by one, by their names. Your teacher will show you how to stretch each one.",
                  grid([(first_word(s, a), f"Surah {Q[s - 1]['transliteration']} {s}:{a}") for s, a in muq], 4, "rtl")))
# Lesson 4 harakat
pages.append(page(4, "Short Vowels: Fatha, Kasra, Damma", "Harakaat: Zabar, Zer, Pesh",
                  "Fatha (zabar) gives an 'a' sound, kasra (zer) an 'i' sound and damma (pesh) a 'u' sound. Read each row from right to left: ba, bi, bu.",
                  grid([c for r in rows_h for c in r], 9, "rtl tight")))
# Lesson 5 tanween
tan = []
for l in ["ا"] + CONS:
    for h in (FT, KT, DT):
        b = ("إ" if h == KT else "أ") if l == "ا" else l
        tan.append((b + h, ""))
pages.append(page(5, "Double Vowels", "Tanween: Do Zabar, Do Zer, Do Pesh",
                  "Tanween adds an 'n' sound at the end: ban, bin, bun. Read each row from right to left.", grid(tan, 9, "rtl tight")))
# Lesson 6 words with harakat (classical past-tense verbs, fully voweled)
words = ["كَتَبَ", "ذَهَبَ", "جَلَسَ", "خَلَقَ", "فَتَحَ", "نَصَرَ", "رَزَقَ", "سَمِعَ", "عَلِمَ", "شَرِبَ", "حَسُنَ", "كَرُمَ", "صَبَرَ", "شَكَرَ", "دَخَلَ", "خَرَجَ", "رَجَعَ", "زَرَعَ"]
pages.append(page(6, "Joining Vowels into Words", "Harakaat ki Mashq",
                  "Now join the letters with their short vowels. Read slowly, one letter at a time, then together: ka-ta-ba, kataba.", grid([(w, "") for w in words], 6, "rtl")))
# Lesson 7 standing vowels
st = []
for l in ["ب", "ت", "ل", "م", "ن", "ه"]:
    st += [(l + KZ, ""), (l + KE, ""), (l + UP, "")]
pages.append(page(7, "Standing Vowels", "Khari Zabar, Khari Zer, Ulta Pesh",
                  "A standing fatha, standing kasra or reversed damma is read long, for two counts: baa, bee, boo.", grid(st, 6, "rtl")))
# Lesson 8 madd letters
md = []
for l in CONS[:24]:
    md += [(l + F + "ا", ""), (l + K + "ي", ""), (l + D + "و", "")]
pages.append(page(8, "Long Vowels", "Huroof-e-Maddah",
                  "Alif after fatha, ya after kasra and waw after damma make the sound long, for two counts: baa, bee, boo.", grid(md, 9, "rtl tight")))
# Lesson 9 leen
ln = []
for l in CONS[:24]:
    ln += [(l + F + "يْ", ""), (l + F + "وْ", "")]
pages.append(page(9, "Soft Letters", "Huroof-e-Leen",
                  "Ya or waw with sukoon after a fatha is read softly and gently: bay, baw. Do not stretch them.", grid(ln, 8, "rtl tight")))
# Lesson 10 sukoon
sk = []
for l in CONS[:24]:
    sk += [("أَ" + l + SUK, ""), ("إِ" + l + SUK, ""), ("أُ" + l + SUK, "")]
pages.append(page(10, "Sukoon", "Jazm",
                  "A letter with sukoon (jazm) has no vowel. Join it to the letter before: ab, ib, ub.", grid(sk, 9, "rtl tight")))
# Lesson 11 tashdeed
sh = []
for l in CONS[:24]:
    sh += [("أَ" + l + SHAD + F, ""), ("أَ" + l + SHAD + K, ""), ("أَ" + l + SHAD + D, "")]
pages.append(page(11, "Doubled Letters", "Tashdeed (Shaddah)",
                  "Shaddah doubles a letter: read it once with sukoon, then again with its vowel: ab-ba, ab-bi, ab-bu.", grid(sh, 9, "rtl tight")))
# Lesson 12 madd sign
mdd = [(l + F + "ا" + MADD + "ءَ", "") for l in ["ج", "ش", "س", "ب", "ف", "ر", "ل", "م", "ن", "ك", "ه", "ت"]]
pages.append(page(12, "The Madd Sign", "Madd",
                  "A madd sign (~) above a long vowel means stretch it longer, about four to five counts. Your teacher will show you the exact length.", grid(mdd, 6, "rtl")))
# Lesson 13 Al-Fatiha
fat = "".join(f'<p class="ayah" lang="ar">{v["text"]} <span class="an">({str(v["id"]).translate(str.maketrans("0123456789", "٠١٢٣٤٥٦٧٨٩"))})</span></p>' for v in Q[0]["verses"])
pages.append(page(13, "Reading Practice: Surah Al-Fatiha", "Quran ki Tilawat",
                  "Well done! Now read Surah Al-Fatiha, the opening of the Quran, slowly and carefully with your teacher. (Madinah Mushaf script.)",
                  f'<div class="fatiha" dir="rtl">{fat}</div>'))


def ff(fam, path, w, style="normal"):
    return f"@font-face{{font-family:'{fam}';src:url('file://{path}') format('woff2');font-weight:{w};font-style:{style}}}"


fonts = "".join([
    ff("Amiri", f"{FONTS}/fontsource-amiri-5.3.0/files/amiri-arabic-400-normal.woff2", 400),
    ff("Amiri", f"{FONTS}/fontsource-amiri-5.3.0/files/amiri-arabic-700-normal.woff2", 700),
    ff("Manrope", f"{FONTS}/fontsource-manrope-5.3.0/files/manrope-latin-500-normal.woff2", 500),
    ff("Manrope", f"{FONTS}/fontsource-manrope-5.3.0/files/manrope-latin-800-normal.woff2", 800),
    ff("Fraunces", f"{FONTS}/fontsource-fraunces-5.3.0/files/fraunces-latin-600-normal.woff2", 600),
])
CSS = fonts + """
@page{size:A4;margin:0}
*{box-sizing:border-box}body{margin:0;font-family:Manrope,sans-serif;color:#2b251c;-webkit-print-color-adjust:exact;print-color-adjust:exact}
.pg{width:210mm;height:297mm;padding:16mm 14mm 14mm;position:relative;page-break-after:always;background:#fbf7ee;overflow:hidden}
.pg header{display:flex;align-items:baseline;gap:12px;flex-wrap:wrap;border-bottom:2px solid #c79b45;padding-bottom:8px;margin-bottom:10px}
.ln{background:#14110c;color:#e2c47e;font-weight:800;font-size:11px;letter-spacing:.14em;text-transform:uppercase;padding:4px 10px;border-radius:99px}
h2{font-family:Fraunces,serif;font-size:25px;margin:0;color:#14110c}.ur{font-size:13px;color:#a97f2e;font-weight:800}
.intro{font-size:12.5px;line-height:1.6;margin:0 0 10px;color:#4a4134}
.grid{display:grid;gap:6px;direction:rtl}.c4{grid-template-columns:repeat(4,1fr)}.c6{grid-template-columns:repeat(6,1fr)}.c8{grid-template-columns:repeat(8,1fr)}.c9{grid-template-columns:repeat(9,1fr)}
.cell{background:#fff;border:1px solid #e6dcc6;border-radius:9px;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:6px 2px;min-height:30mm}
.tight .cell{min-height:20mm;padding:2px}
.ar{font-family:Amiri,serif;font-size:36px;line-height:1.7;color:#14110c}
.big .ar{font-size:52px;line-height:1.5}.big .cell{min-height:36mm}.tight .ar{font-size:29px;line-height:1.6}
.shapes .ar{font-size:30px;letter-spacing:2px}
.nm{font-size:10px;font-weight:800;color:#a97f2e;letter-spacing:.06em;text-transform:uppercase}
.fatiha{background:#fff;border:1px solid #e6dcc6;border-radius:14px;padding:14px 20px}
.ayah{font-family:Amiri,serif;font-size:31px;line-height:2.15;margin:0;text-align:right}.an{color:#a97f2e;font-size:22px}
.pg footer{position:absolute;left:14mm;right:14mm;bottom:8mm;font-size:9.5px;color:#8a7d64;text-align:center;border-top:1px solid #e6dcc6;padding-top:5px}
.cover{background:#14110c;color:#efe3c4;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:24mm}
.cover .frame{border:2px solid #c79b45;border-radius:200px 200px 18px 18px;padding:40mm 16mm 24mm;width:100%;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;
 background:radial-gradient(circle at 50% 30%,rgba(199,155,69,.35),transparent 60%)}
.cover .ar{color:#fbf7ee;font-size:60px;line-height:1.4}.cover h1{font-family:Fraunces,serif;font-size:42px;margin:0;color:#e2c47e}
.cover p{margin:0;font-size:15px;line-height:1.6;max-width:120mm}.cover .brand{margin-top:16mm;font-weight:800;letter-spacing:.2em;font-size:12px;color:#e2c47e}
.howto{font-size:13.5px;line-height:1.7}.howto li{margin:0 0 8px}
"""
cover = ('<section class="pg cover"><div class="frame"><div class="ar" lang="ar">القَاعِدَةُ النُّورَانِيَّة</div><h1>Noorani Qaida</h1>'
         '<p>Learn to read the Quran step by step, from the very first letter. A free practice book for children and adults.</p>'
         '<p style="color:#cdb98d">13 lessons · Arabic letters · harakat · tanween · madd · sukoon · shaddah · Surah Al-Fatiha</p>'
         '<div class="brand">QURAN ONLINE TARTEEL · SINCE 2010</div><p style="font-size:12.5px">quranonlinetarteel.net · WhatsApp +92 335 0548488</p></div></section>')
howto = ('<section class="pg"><header><span class="ln">Before You Start</span><h2>How to Use This Qaida</h2><span class="ur">Walidain ke liye</span></header>'
         '<ol class="howto"><li><b>Little and often.</b> Ten to fifteen minutes every day works better than one long session a week.</li>'
         '<li><b>Read right to left.</b> Arabic starts on the right. Point to each box as you read.</li>'
         '<li><b>Sound first, speed later.</b> Say each letter clearly from its correct place in the mouth. Speed comes naturally.</li>'
         '<li><b>Don\'t skip lessons.</b> Each lesson builds on the one before. Move on only when the current page is easy.</li>'
         '<li><b>Use a teacher.</b> A book cannot hear you. A teacher corrects the small mistakes that are hard to fix later. '
         'Quran Online Tarteel offers live one-to-one Noorani Qaida classes with female teachers, and the first 2 classes are free.</li>'
         '<li><b>Make dua.</b> Begin each session with <i>Rabbi zidni ilma</i>, "My Lord, increase me in knowledge" (Quran 20:114).</li></ol>'
         '<footer>quranonlinetarteel.net · Free for personal and family use · Learn with a female teacher: 2 free classes</footer></section>')
end = ('<section class="pg cover"><div class="frame"><div class="ar" lang="ar">مَا شَاءَ الله</div><h1>Well Done!</h1>'
       '<p>You have completed the Noorani Qaida practice book. The next step is reading the Quran itself with Tajweed.</p>'
       '<p>Book 2 free live classes with a female teacher:<br><b style="color:#e2c47e">quranonlinetarteel.net/free-trial</b></p>'
       '<div class="brand">QURAN ONLINE TARTEEL</div><p style="font-size:12.5px">Noorani Qaida · Quran Reading · Tajweed · Hifz · Islamic Studies</p></div></section>')
doc = f'<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Noorani Qaida - Quran Online Tarteel</title><style>{CSS}</style></head><body>{cover}{howto}{"".join(pages)}{end}</body></html>'
open(OUT_HTML, "w").write(doc)
os.makedirs(os.path.dirname(OUT_PDF), exist_ok=True)
js = f"""const {{chromium}}=require('playwright');(async()=>{{const b=await chromium.launch();const p=await b.newPage();
await p.goto('file://{OUT_HTML}',{{waitUntil:'networkidle'}});await p.evaluate(()=>document.fonts.ready);
await p.pdf({{path:'{OUT_PDF}',format:'A4',printBackground:true,preferCSSPageSize:true}});await b.close();}})();"""
subprocess.run(["node", "-e", js], check=True)
print("PDF:", OUT_PDF, os.path.getsize(OUT_PDF) // 1024, "KB")
